{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-hybrid-search",
  "version": "0.1.1",
  "type": "module",
  "description": "Hybrid worktree search plugin for OpenCode - fast code search in large repositories",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "bin": {
    "opencode-hybrid-search-refresh": "dist/bin/refresh.js",
    "opencode-hybrid-search-install-hooks": "dist/bin/install-hooks.js"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "bun test",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "prepublishOnly": "bun run build && bun test",
    "index:refresh": "bun run src/bin/refresh.ts",
    "index:install-hooks": "bun run src/bin/install-hooks.ts"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wkronmiller/opencode-hybrid-search.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "search",
    "grep",
    "git",
    "worktree",
    "ripgrep",
    "code-search"
  ],
  "author": "wkronmiller",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/wkronmiller/opencode-hybrid-search/issues"
  },
  "homepage": "https://github.com/wkronmiller/opencode-hybrid-search#readme",
  "engines": {
    "node": ">=18.0.0"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.4.11",
    "minimatch": "^10.0.3",
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@types/bun": "^1.3.11",
    "typescript": "^5.8.2"
  }
}
